"""Shared normalization and serialization for row exports."""

import csv
import io
import json


_FIELDS = ("id", "name")


def _normalize_rows(rows):
    for row in rows:
        yield {
            key: "" if row.get(key) is None else str(row[key])
            for key in _FIELDS
        }


def export_rows(rows, format):
    """Export id and name fields as CSV or compact JSON."""
    if format == "csv":
        buffer = io.StringIO(newline="")
        writer = csv.DictWriter(buffer, fieldnames=_FIELDS, lineterminator="\n")
        writer.writeheader()
        writer.writerows(_normalize_rows(rows))
        return buffer.getvalue()
    if format == "json":
        return json.dumps(
            list(_normalize_rows(rows)), ensure_ascii=False, separators=(",", ":")
        )
    raise ValueError("unsupported format")

